    Uses X-API-Key auth header, 'input' field (not 'messages'),
    and polls async result from /v1/result/{task_id}.
    """
    HERMES_KEY = os.getenv("HERMES_API_KEY", "hermes-secret-change-me-in-production")
    full_input = f"{system}\n\n{prompt}"
