        import httpx
        # Submit task to cognitive path
        r = httpx.post(f"{HERMES_API}/v1/portsocket",
            headers={
                "Content-Type": "application/json",
                "X-API-Key": HERMES_KEY,
                "X-Agent-ID": "senator-execution",
            },
            json={"input": full_input[:30000], "mode": "auto"},
            timeout=30)
        if r.status_code != 200:
            print(f"  Hermes submit failed: {r.status_code} {r.text[:200]}", file=sys.stderr)
            return None
        task_data = r.json()
        task_id = task_data.get("task_id")
        if not task_id:
            print(f"  Hermes: no task_id in response", file=sys.stderr)
            return None
        print(f"  Hermes task: {task_id} (polling...)")
        # Poll for result
        for attempt in range(int(timeout / 3)):
            import time
            time.sleep(3)
            pr = httpx.get(f"{HERMES_API}/v1/result/{task_id}",
                headers={"X-API-Key": HERMES_KEY},
                timeout=15)
            if pr.status_code != 200:
                continue
            result_data = pr.json()
            status = result_data.get("status", "")
            if status == "SUCCESS":
                result_obj = result_data.get("result", {})
                # Try to get actual LLM response
                if isinstance(result_obj, dict):
                    # Check results array
                    results = result_obj.get("results", [])
                    if results:
                        return str(results[0]) if results else None
                    # Check plan
                    plan = result_obj.get("plan")
                    if plan:
                        return str(plan)
                    # Fallback: return whole result as string
                    return json.dumps(result_obj, ensure_ascii=False)
                return str(result_obj)
            elif status == "FAILURE":
                err = result_data.get("error", "unknown")
                print(f"  Hermes task failed: {err}", file=sys.stderr)
                return None
            # else: still PENDING/STARTED, keep polling
        print(f"  Hermes task timed out after {timeout}s", file=sys.stderr)
        return None
